function area(seed=0,color='#659dcb'){const vals=[63,60,39,69,64,54,66].map((n,i)=>n+Math.sin(i+seed)*8);const pts=vals.map((y,i)=>`${18+i*26},${y}`).join(' ');return `<svg viewBox="0 0 190 99" role="img" aria-label="Serie temporal"><defs><linearGradient id="area${seed}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${color}" stop-opacity=".5"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${[25,45,65,85].map(y=>`<path d="M15 ${y}H182" stroke="#6588981a"/>`).join('')}<polygon points="18,85 ${pts} 174,85" fill="url(#area${seed})"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.5"/><polyline points="${vals.map((y,i)=>`${18+i*26},${y+9}`).join(' ')}" fill="none" stroke="#8582c3" stroke-width="1"/>${['06','09','12','15','18','21','24'].map((n,i)=>`<text x="${18+i*26}" y="98" fill="#6f8797" font-size="8">${n}</text>`).join('')}</svg>`;}
function trainDiagram(){return `<div class="trainDiagram">${Array.from({length:5},()=>'<div class="carDiagram"><i></i><i></i><i></i></div>').join('')}</div>`;}
function stats(items){return `<div class="stats">${items.map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join('')}</div>`;}
function panel(title,body,style=''){return `<section class="panel" style="${style}"><h2>${tr(title)}<small>···</small></h2>${body}</section>`;}
function table(count=6,type='line'){return `<table class="rows"><thead><tr><th>${tr(type==='line'?'networkGroup':'device')}</th><th>${tr('status')}</th><th>${state.lang==='en'?'Value':'Valor'}</th></tr></thead><tbody>${Array.from({length:count},(_,i)=>`<tr><td>${type==='line'?(state.lang==='en'?`Line ${i+1}`:`Línea ${i+1}`):['HVAC','CCTV','AFC','PSD','FAS','UPS','BAS'][i%7]+'-'+String(i+1).padStart(2,'0')}</td><td class="${state.alarm&&i===4?'bad':'good'}">${state.alarm&&i===4?'ALARM':(state.lang==='en'?'OK':'OK')}</td><td>${type==='line'?(98.4-i*.13).toFixed(2)+'%':(i%2?24+i+' °C':'100%')}</td></tr>`).join('')}</tbody></table>`;}
function progression(){return ['1','2','4','5'].map((n,i)=>`<div class="progressRow"><span>${state.lang==='en'?n:'L'+[1,2,4,5][i]}</span><div class="track"><i style="width:${88-i*13}%;background:linear-gradient(90deg,#1c334b,${lineColors[i]})"></i></div><b>${[48.1,36.5,33.5,26.4][i]}</b></div>`).join('');}
function p6Options(values,selected,prefix=''){return `<option value="">Todos</option>${values.map(value=>{const label=prefix&&/^UE/i.test(value)?value:prefix+value;return `<option value="${safe(value)}" ${value===selected?'selected':''}>${safe(label)}</option>`;}).join('')}`;}
function p6UESummary(){const count=p6Selection.ues.length;if(!count)return 'Todas';if(count===1){const value=p6Selection.ues[0];return /^UE/i.test(value)?value:`UE ${value}`;}return `${count} UE seleccionadas`;}
function p6UEPicker(){return `<details class="p6Multi"><summary>${safe(p6UESummary())}</summary><div class="p6MultiMenu"><input type="search" data-p6-ue-search placeholder="Buscar UE" aria-label="Buscar unidad de ejecución"><div class="p6UEOptions">${p6UEs.map(value=>{const label=/^UE/i.test(value)?value:`UE ${value}`;return `<label data-p6-ue-option><input type="checkbox" value="${safe(value)}" ${p6Selection.ues.includes(value)?'checked':''}><span>${safe(label)}</span></label>`;}).join('')}</div><div class="p6MultiActions"><button data-p6-ue-clear>Limpiar</button><button data-p6-ue-apply>Aplicar</button></div></div></details>`;}
function p6Stack(counts){const total=Object.values(counts).reduce((sum,value)=>sum+value,0)||1;return `<div class="p6Stack" aria-label="Distribución por estado">${Object.entries(P6_STATUS).map(([key,status])=>`<i class="${key}" title="${status.label}: ${counts[key]||0}" style="--state:${status.color};width:${(counts[key]||0)/total*100}%"></i>`).join('')}</div>`;}
